CREATE TABLE IF NOT EXISTS empresas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,ruc VARCHAR(20) UNIQUE,correo VARCHAR(180),telefono VARCHAR(40),direccion VARCHAR(250),activa BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usuarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT REFERENCES empresas(id),nombre VARCHAR(160) NOT NULL,usuario VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,rol VARCHAR(30) NOT NULL DEFAULT 'Tecnico',activo BOOLEAN NOT NULL DEFAULT TRUE,ultimo_acceso TIMESTAMPTZ,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS equipos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT REFERENCES empresas(id),codigo VARCHAR(40) NOT NULL,nombre VARCHAR(140) NOT NULL,marca VARCHAR(80) DEFAULT '',modelo VARCHAR(80) DEFAULT '',serie VARCHAR(100) DEFAULT '',horometro DOUBLE PRECISION NOT NULL DEFAULT 0,ubicacion VARCHAR(180) DEFAULT '',estado VARCHAR(35) NOT NULL DEFAULT 'Operativo',creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mantenimientos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT REFERENCES empresas(id),equipo_id BIGINT NOT NULL REFERENCES equipos(id),tipo VARCHAR(30) NOT NULL,descripcion TEXT NOT NULL,fecha DATE NOT NULL,horometro_objetivo DOUBLE PRECISION,intervalo_horas DOUBLE PRECISION,responsable VARCHAR(140) DEFAULT '',estado VARCHAR(30) NOT NULL DEFAULT 'Pendiente',creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fallas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT REFERENCES empresas(id),equipo_id BIGINT NOT NULL REFERENCES equipos(id),descripcion TEXT NOT NULL,prioridad VARCHAR(20) NOT NULL DEFAULT 'Media',fecha DATE NOT NULL,responsable VARCHAR(140) DEFAULT '',estado VARCHAR(30) NOT NULL DEFAULT 'Abierta',observaciones TEXT DEFAULT '',creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS empresa_id BIGINT REFERENCES empresas(id);
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS activo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS ultimo_acceso TIMESTAMPTZ;
ALTER TABLE equipos ADD COLUMN IF NOT EXISTS empresa_id BIGINT REFERENCES empresas(id);
ALTER TABLE equipos ADD COLUMN IF NOT EXISTS serie VARCHAR(100) DEFAULT '';
ALTER TABLE equipos ADD COLUMN IF NOT EXISTS horometro DOUBLE PRECISION NOT NULL DEFAULT 0;
ALTER TABLE equipos ADD COLUMN IF NOT EXISTS ubicacion VARCHAR(180) DEFAULT '';
ALTER TABLE mantenimientos ADD COLUMN IF NOT EXISTS empresa_id BIGINT REFERENCES empresas(id);
ALTER TABLE mantenimientos ADD COLUMN IF NOT EXISTS horometro_objetivo DOUBLE PRECISION;
ALTER TABLE mantenimientos ADD COLUMN IF NOT EXISTS intervalo_horas DOUBLE PRECISION;
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS empresa_id BIGINT REFERENCES empresas(id);
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS prioridad VARCHAR(20) NOT NULL DEFAULT 'Media';
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS responsable VARCHAR(140) DEFAULT '';
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS observaciones TEXT DEFAULT '';
INSERT INTO empresas (nombre,slug) VALUES ('Empresa inicial MAQCONTROL','maqcontrol-inicial') ON CONFLICT (slug) DO NOTHING;
UPDATE usuarios SET empresa_id=(SELECT id FROM empresas WHERE slug='maqcontrol-inicial') WHERE empresa_id IS NULL;
UPDATE equipos SET empresa_id=(SELECT id FROM empresas WHERE slug='maqcontrol-inicial') WHERE empresa_id IS NULL;
UPDATE mantenimientos SET empresa_id=(SELECT id FROM empresas WHERE slug='maqcontrol-inicial') WHERE empresa_id IS NULL;
UPDATE fallas SET empresa_id=(SELECT id FROM empresas WHERE slug='maqcontrol-inicial') WHERE empresa_id IS NULL;
CREATE INDEX IF NOT EXISTS ix_equipos_empresa_estado ON equipos(empresa_id,estado);
CREATE INDEX IF NOT EXISTS ix_mantenimientos_empresa_fecha ON mantenimientos(empresa_id,fecha);
CREATE INDEX IF NOT EXISTS ix_fallas_empresa_estado ON fallas(empresa_id,estado);
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuarios_empresa_usuario ON usuarios(empresa_id,usuario);
CREATE UNIQUE INDEX IF NOT EXISTS uq_equipos_empresa_codigo ON equipos(empresa_id,codigo);
CREATE TABLE IF NOT EXISTS lecturas_horometro (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),equipo_id BIGINT NOT NULL REFERENCES equipos(id),lectura DOUBLE PRECISION NOT NULL CHECK(lectura>=0),observacion TEXT DEFAULT '',registrado_por BIGINT REFERENCES usuarios(id),registrado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ordenes_trabajo (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),equipo_id BIGINT NOT NULL REFERENCES equipos(id),mantenimiento_id BIGINT REFERENCES mantenimientos(id),codigo VARCHAR(40) NOT NULL,titulo VARCHAR(180) NOT NULL,descripcion TEXT DEFAULT '',tecnico VARCHAR(140) DEFAULT '',estado VARCHAR(30) NOT NULL DEFAULT 'Pendiente',fecha_programada DATE,fecha_inicio TIMESTAMPTZ,fecha_fin TIMESTAMPTZ,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notificaciones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),equipo_id BIGINT REFERENCES equipos(id),tipo VARCHAR(40) NOT NULL,titulo VARCHAR(180) NOT NULL,mensaje TEXT NOT NULL,leida BOOLEAN NOT NULL DEFAULT FALSE,creada_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auditoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),usuario_id BIGINT REFERENCES usuarios(id),accion VARCHAR(80) NOT NULL,entidad VARCHAR(80) NOT NULL,entidad_id BIGINT,detalle TEXT DEFAULT '',ip VARCHAR(64),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS prioridad VARCHAR(20) NOT NULL DEFAULT 'Media';
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS responsable VARCHAR(140) DEFAULT '';
ALTER TABLE fallas ADD COLUMN IF NOT EXISTS observaciones TEXT DEFAULT '';
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS activo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS ultimo_acceso TIMESTAMPTZ;
